export class ConfError extends Error {}

const BARE = /[A-Za-z0-9_-]/
const isWs = (c) => c === ' ' || c === '\t'
const T = (map) => ({ t: 'table', map, hdr: false })

function fail(msg) { throw new ConfError(msg) }

class Line {
  constructor(s) { this.s = s; this.i = 0 }
  get c() { return this.s[this.i] }
  ws() { while (isWs(this.s[this.i])) this.i++ }
  atEnd() { return this.i >= this.s.length }
  atComment() { return this.c === '#' || this.c === ';' }
  tailOk() { this.ws(); return this.atEnd() || this.atComment() }

  basicString() {
    this.i++
    let out = ''
    for (;;) {
      if (this.atEnd()) fail('unterminated string')
      const c = this.c
      this.i++
      if (c === '"') return out
      if (c !== '\\') { out += c; continue }
      if (this.atEnd()) fail('unterminated string')
      const e = this.c
      this.i++
      if (e === '"') out += '"'
      else if (e === '\\') out += '\\'
      else if (e === 'n') out += '\n'
      else if (e === 't') out += '\t'
      else if (e === 'r') out += '\r'
      else if (e === '0') out += '\0'
      else if (e === 'u') {
        const h = this.s.slice(this.i, this.i + 4)
        if (!/^[0-9A-Fa-f]{4}$/.test(h)) fail('invalid escape \\u')
        out += String.fromCharCode(parseInt(h, 16))
        this.i += 4
      } else fail('invalid escape \\' + String.fromCodePoint(e.codePointAt(0) === e.charCodeAt(0) ? e.charCodeAt(0) : e.codePointAt(0)))
    }
  }

  literalString() {
    const j = this.s.indexOf("'", this.i + 1)
    if (j < 0) fail('unterminated string')
    const r = this.s.slice(this.i + 1, j)
    this.i = j + 1
    return r
  }

  name() {
    const c = this.c
    if (c === '"') return this.basicString()
    if (c === "'") return this.literalString()
    const st = this.i
    while (!this.atEnd() && BARE.test(this.c)) this.i++
    if (st === this.i) fail('expected a name')
    return this.s.slice(st, this.i)
  }

  dotted() {
    const names = []
    this.ws()
    names.push(this.name())
    for (;;) {
      const save = this.i
      this.ws()
      if (this.c === '.') {
        this.i++
        this.ws()
        names.push(this.name())
      } else { this.i = save; return names }
    }
  }

  value() {
    this.ws()
    if (this.atEnd() || this.atComment() || ',]}'.includes(this.c)) fail('expected a value')
    const c = this.c
    if (c === '"') return { t: 'string', v: this.basicString() }
    if (c === "'") return { t: 'string', v: this.literalString() }
    if (c === '[') return this.array()
    if (c === '{') return this.inline()
    const st = this.i
    while (!this.atEnd() && !isWs(this.c) && !',]};'.includes(this.c)) this.i++
    const w = this.s.slice(st, this.i)
    if (w === 'true') return { t: 'boolean', v: true }
    if (w === 'false') return { t: 'boolean', v: false }
    const D = '\\d+(?:_\\d+)*'
    if (new RegExp(`^[+-]?${D}$`).test(w)) return { t: 'integer', v: Number(w.replace(/_/g, '')) }
    if (new RegExp(`^[+-]?${D}(?:\\.${D}(?:[eE][+-]?${D})?|[eE][+-]?${D})$`).test(w)) return { t: 'float', v: Number(w.replace(/_/g, '')) }
    fail('invalid value ' + w)
  }

  array() {
    this.i++
    const items = []
    for (;;) {
      this.ws()
      if (this.atEnd() || this.atComment()) fail('unterminated array')
      if (this.c === ']') { this.i++; return { t: 'array', items, aot: false } }
      items.push(this.value())
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === ']') { this.i++; return { t: 'array', items, aot: false } }
      fail('unterminated array')
    }
  }

  inline() {
    this.i++
    const tbl = T(new Map())
    this.ws()
    if (this.c === '}') { this.i++; return tbl }
    for (;;) {
      this.ws()
      if (this.atEnd() || this.atComment()) fail('unterminated inline table')
      const names = this.dotted()
      this.ws()
      if (this.c !== '=') fail('expected = in an inline table')
      this.i++
      const v = this.value()
      assign(tbl, [], names, v)
      this.ws()
      if (this.c === ',') { this.i++; continue }
      if (this.c === '}') { this.i++; return tbl }
      fail('unterminated inline table')
    }
  }
