  const parent = walk(root, [], names.slice(0, -1))
  const last = names[names.length - 1]
  const path = names.join('.')
  const ex = parent.map.get(last)
  if (isArr) {
    if (!ex) {
      const t = T(new Map())
      parent.map.set(last, { t: 'array', items: [t], aot: true })
      return t
    }
    if (ex.t !== 'array' || !ex.aot) fail(`${path} is not an array of tables`)
    const t = T(new Map())
    ex.items.push(t)
    return t
  }
  if (!ex) {
    const t = T(new Map())
    t.hdr = true
    parent.map.set(last, t)
    return t
  }
  if (ex.t !== 'table') fail(`${path} is not a table`)
  if (ex.hdr) fail(`table ${path} is defined twice`)
  ex.hdr = true
  return ex
}

export function parse(text) {
  const lines = text.split('\n')
  if (lines[lines.length - 1] === '') lines.pop()
  const root = T(new Map())
  let cur = root
  let curPath = []
  lines.forEach((raw, idx) => {
    try {
      const L = new Line(raw)
      L.ws()
      if (L.atEnd() || L.atComment()) return
      if (L.c === '[') {
        const isArr = raw[L.i + 1] === '['
        L.i += isArr ? 2 : 1
        const names = L.dotted()
        L.ws()
        if (L.c !== ']') fail('unterminated table header')
        L.i++
        if (isArr) {
          if (L.c !== ']') fail('unterminated table header')
          L.i++
        }
        if (!L.tailOk()) fail('trailing text after a table header')
        cur = header(root, names, isArr)
        curPath = names
        return
      }
      const names = L.dotted()
      L.ws()
      if (L.c !== '=') fail('expected key = value')
      L.i++
      const v = L.value()
      if (!L.tailOk()) fail('trailing text after a value')
      assign(cur, curPath, names, v)
    } catch (e) {
      if (e instanceof ConfError) e.message = `line ${idx + 1}: ${e.message}`
      throw e
    }
  })
  return root
}
