import { readFileSync } from 'node:fs'
import { parse, ConfError } from './parser.js'

const mode = process.argv.slice(2)
if (mode.length !== 1 || (mode[0] !== 'json' && mode[0] !== 'keys')) {
  process.stderr.write('error: usage: cli.js json|keys\n')
  process.exit(2)
}

const cmp = (a, b) => {
  const x = Array.from(a, (c) => c.codePointAt(0))
  const y = Array.from(b, (c) => c.codePointAt(0))
  for (let i = 0; i < x.length && i < y.length; i++) if (x[i] !== y[i]) return x[i] - y[i]
  return x.length - y.length
}
const sorted = (m) => [...m.keys()].sort(cmp)

function json(n, ind) {
  const pad = '  '.repeat(ind + 1)
  const end = '  '.repeat(ind)
  if (n.t === 'table') {
    const ks = sorted(n.map)
    if (!ks.length) return '{}'
    return '{\n' + ks.map((k) => `${pad}${JSON.stringify(k)}: ${json(n.map.get(k), ind + 1)}`).join(',\n') + '\n' + end + '}'
  }
  if (n.t === 'array') {
    if (!n.items.length) return '[]'
    return '[\n' + n.items.map((x) => pad + json(x, ind + 1)).join(',\n') + '\n' + end + ']'
  }
  return JSON.stringify(n.v)
}

function keys(n, path, out) {
  if (n.t === 'table') {
    for (const k of sorted(n.map)) {
      const c = n.map.get(k)
      const p = path === null ? k : path + '.' + k
      out.push(`${p} ${c.t}`)
      keys(c, p, out)
    }
  } else if (n.t === 'array') {
    n.items.forEach((c, i) => {
      const p = `${path}[${i}]`
      out.push(`${p} ${c.t}`)
      keys(c, p, out)
    })
  }
}

let root
try {
  root = parse(readFileSync(0, 'utf8'))
} catch (e) {
  if (!(e instanceof ConfError)) throw e
  process.stderr.write('error: ' + e.message + '\n')
  process.exit(2)
}
if (mode[0] === 'json') process.stdout.write(json(root, 0) + '\n')
else {
  const out = []
  keys(root, null, out)
  process.stdout.write(out.map((l) => l + '\n').join(''))
}
